export const LESSONS: Lesson[] = [{"id":"check-and-mate","title":{"en":"Check and Checkmate","zh":"将军与将死"},"summary":{"en":"Attack the general; trap it to win.","zh":"攻击老将，困死它就赢了。"},"steps":[{"type":"explain","fen":"4k4/9/9/9/4R4/9/9/9/9/3K5 b - - 0 1","arrows":[{"from":"e5","to":"e9","color":"red"}],"text":{"en":"When a piece attacks the general, that's check (将军). The other side must answer it at once: move the general, block, or capture the attacker.","zh":"攻击对方的将（帅）叫“将军”。对方必须马上应将：走开老将、垫子挡住，或吃掉将军的棋子。"}},{"type":"find-move","fen":"4k4/R8/6N2/9/9/9/9/9/5R3/3K5 w - - 0 1","accept":"checkmate","text":{"en":"Checkmate means check with no way out. Find a move that checkmates Black.","zh":"将死就是被将军后无法应将。找一步把黑方将死。"},"hint":{"en":"Your horse already guards e8. Use a chariot to check.","zh":"你的马已经控制了e8。用车来将军。"},"wrong":{"en":"Black can still escape. Try another check.","zh":"黑将还能逃走。换一步将军试试。"},"success":{"en":"Checkmate! Black's general has nowhere to go.","zh":"将死了！黑将无路可逃。"}},{"type":"play-out","fen":"4k4/9/9/9/9/9/9/1R7/R8/3K5 w - - 0 1","goal":"checkmate","maxMoves":4,"text":{"en":"Two chariots against a lone general. Checkmate Black in at most 4 moves — Black will defend.","zh":"双车对单将。最多走4步将死黑方——黑方会防守。"},"hint":{"en":"Use one chariot to cut off a rank, then check with the other on the next rank.","zh":"一个车封住一条横线，另一个车在旁边那条横线将军。"},"success":{"en":"Well done! This two-chariot mate (双车错) is a pattern worth remembering.","zh":"很好！这个双车错杀法值得牢记。"}},{"type":"quiz","text":{"en":"A player has no legal move but is not in check. What happens?","zh":"一方无棋可走，但没有被将军，结果是什么？"},"options":[{"text":{"en":"That player loses","zh":"这一方输"},"correct":true},{"text":{"en":"It's a draw","zh":"和棋"}},{"text":{"en":"They skip a turn","zh":"跳过这一步"}}],"explanation":{"en":"In Xiangqi, having no legal move always loses (困毙), unlike chess where stalemate is a draw.","zh":"象棋中无子可动就输（困毙），这和国际象棋的逼和不同。"}}]},{"id":"first-game","title":{"en":"Your First Game","zh":"第一盘棋"},"summary":{"en":"Good opening habits, then play a bot.","zh":"开局的好习惯，然后和机器人下一盘。"},"steps":[{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","text":{"en":"Good opening habits: bring out your horses and chariots, control the centre, and keep your general safe.","zh":"开局的好习惯：出马出车，控制中路，保护老帅。"}},{"type":"find-move","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","accept":["h2e2","b2e2"],"text":{"en":"A classic first move is the Central Cannon (中炮): move a cannon to the middle file.","zh":"经典的第一步是“中炮”：把一个炮移到中路。"},"hint":{"en":"Slide a cannon sideways to file 5.","zh":"把一个炮横移到“五”路。"},"wrong":{"en":"Good try — but put a cannon on the middle file.","zh":"不错的尝试——不过请把炮放到中路。"},"success":{"en":"炮二平五 — the most popular opening of all.","zh":"炮二平五——最流行的开局。"}},{"type":"find-move","fen":"rnbakab1r/9/1c4nc1/p1p1p1p1p/9/9/P1P1P1P1P/1C2C4/9/RNBAKABNR w - - 2 2","accept":["h0g2","b0c2"],"text":{"en":"Black answered with a horse. Now bring out one of your horses.","zh":"黑方跳马应对。现在你也跳出一个马。"},"hint":{"en":"A horse jumps up toward the centre.","zh":"马向中间跳出来。"},"wrong":{"en":"Try developing a horse instead.","zh":"试试先出马。"},"success":{"en":"Good development! Next, get your chariots moving.","zh":"出子很好！接下来让车动起来。"}},{"type":"quiz","text":{"en":"Which is a good first move?","zh":"哪一步是好的第一步？"},"options":[{"text":{"en":"炮二平五 (Central Cannon)","zh":"炮二平五（中炮）"},"correct":true},{"text":{"en":"帅五进一 (general forward)","zh":"帅五进一（老帅上前）"}},{"text":{"en":"兵九进一 (edge soldier)","zh":"兵九进一（边兵）"}}],"explanation":{"en":"The central cannon aims straight at Black's general and helps your other pieces come out.","zh":"中炮直指黑将，也有利于其他棋子出动。"}},{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","text":{"en":"You know all the pieces and rules now. Go and play your first game against a bot — Little Soldier is waiting!","zh":"你已经学会了所有棋子和规则。去和机器人下第一盘棋吧——小兵在等你！"}}]},{"id":"special-rules","title":{"en":"Special Rules","zh":"特殊规则"},"summary":{"en":"Flying general, no legal move loses, no perpetual check.","zh":"将帅不能照面、困毙判负、禁止长将。"},"steps":[{"type":"explain","fen":"4k4/9/9/9/9/4C4/9/9/9/4K4 w - - 0 1","text":{"en":"The two generals may never face each other on an open file (将帅不能照面). Here only your cannon stands between them.","zh":"两个老将不能在同一条纵线上直接相对（将帅不能照面）。现在只有你的炮挡在中间。"}},{"type":"show-moves","fen":"4k4/9/9/9/9/4C4/9/9/9/4K4 w - - 0 1","square":"e4","text":{"en":"So the cannon may move up and down the file, but not sideways: that would leave the generals facing.","zh":"所以这个炮只能在这条纵线上走，不能横走，否则老将就照面了。"},"restricted":true},{"type":"find-move","fen":"3k5/R8/9/9/9/9/9/9/1R7/4K4 w - - 0 1","accept":"checkmate","text":{"en":"Your general can help in the attack: Black's general may not step onto the e-file while yours faces it. Find the checkmate.","zh":"你的老帅也能参与进攻：黑将不能走到和红帅照面的e线上。找出将死的一步。"},"hint":{"en":"The chariot on a8 already covers rank 8. Check along rank 9 or the d-file.","zh":"a8的车已经封住了第8条横线。在第9横线或d线上将军。"},"wrong":{"en":"Black still has an escape.","zh":"黑将还有退路。"},"success":{"en":"Checkmate! The facing-generals rule took away the e9 escape.","zh":"将死！“将帅不能照面”的规则封住了e9这个退路。"}},{"type":"explain","fen":"4k4/9/6N2/9/9/9/9/9/3R1R3/3K5 b - - 0 1","text":{"en":"Black to move here has no legal move and is not in check. In Xiangqi that is a loss for Black (困毙).","zh":"黑方走棋，但无棋可走，也没有被将军。在象棋里，这是黑方输（困毙）。"}},{"type":"explain","text":{"en":"You may not check forever. If the same position keeps repeating because one side checks every move, the checking side loses (长将判负). Chasing the same unprotected piece forever is also forbidden.","zh":"不能一直将军。如果因为一方不停将军而局面反复出现，将军的一方判负（长将判负）。一直捉同一个没有保护的子也是禁止的。"}},{"type":"quiz","text":{"en":"Red checks on every move and the position repeats three times. Who loses?","zh":"红方每步都将军，局面重复了三次。谁输？"},"options":[{"text":{"en":"Red, for perpetual check","zh":"红方，长将判负"},"correct":true},{"text":{"en":"Black","zh":"黑方"}},{"text":{"en":"Nobody: it's a draw","zh":"没人输，和棋"}}],"explanation":{"en":"Perpetual check is not allowed: the checking side must change or lose.","zh":"长将是不允许的：将军的一方必须变着，否则判负。"}}]},{"id":"the-advisor","title":{"en":"The Advisor","zh":"仕士"},"summary":{"en":"One step diagonally, guarding the general.","zh":"斜走一步，守护老将。"},"steps":[{"type":"show-moves","fen":"3k5/9/9/9/9/9/9/9/4A4/4K4 w - - 0 1","square":"e1","text":{"en":"The advisor moves one point diagonally and, like the general, never leaves the palace.","zh":"士（仕）斜走一步，和将帅一样不能离开九宫。"}},{"type":"capture-stars","fen":"3k5/9/9/9/9/9/9/9/9/3AK4 w - - 0 1","square":"d0","stars":["e1","f2"],"maxMoves":4,"text":{"en":"Collect the stars with your advisor, moving diagonally.","zh":"用仕斜着走，吃掉星星。"}},{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","highlights":[{"square":"d0","kind":"hint"},{"square":"f0","kind":"hint"},{"square":"e1","kind":"hint"},{"square":"d2","kind":"hint"},{"square":"f2","kind":"hint"}],"text":{"en":"Those are the only five points an advisor can ever stand on. Advisors are defenders: keep them near your general.","zh":"仕只能站在这五个点上。仕是防守的棋子，要守在老帅身边。"}},{"type":"quiz","text":{"en":"On how many points can an advisor stand?","zh":"仕一共能站在几个点上？"},"options":[{"text":{"en":"5","zh":"5个"},"correct":true},{"text":{"en":"9","zh":"9个"}},{"text":{"en":"4","zh":"4个"}}],"explanation":{"en":"Five: the four corners and the centre of the palace.","zh":"5个：九宫的四个角和中心。"}}]},{"id":"the-board","title":{"en":"The Board","zh":"棋盘"},"summary":{"en":"Points, files, the river and the palaces.","zh":"交叉点、纵线、河界与九宫。"},"steps":[{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","text":{"en":"Welcome! In Xiangqi the pieces stand on the points where lines cross, not inside the squares. The board has 9 files and 10 ranks.","zh":"欢迎！象棋的棋子放在线与线的交叉点上，而不是格子里。棋盘有9条纵线、10条横线。"}},{"type":"explain","fen":"4k4/9/9/9/9/9/9/9/9/3K5 w - - 0 1","highlights":[{"square":"a4","kind":"hint"},{"square":"b4","kind":"hint"},{"square":"c4","kind":"hint"},{"square":"d4","kind":"hint"},{"square":"e4","kind":"hint"},{"square":"f4","kind":"hint"},{"square":"g4","kind":"hint"},{"square":"h4","kind":"hint"},{"square":"i4","kind":"hint"},{"square":"a5","kind":"hint"},{"square":"b5","kind":"hint"},{"square":"c5","kind":"hint"},{"square":"d5","kind":"hint"},{"square":"e5","kind":"hint"},{"square":"f5","kind":"hint"},{"square":"g5","kind":"hint"},{"square":"h5","kind":"hint"},{"square":"i5","kind":"hint"}],"text":{"en":"The empty band across the middle is the river (楚河 汉界). Some pieces change how they move once they cross it.","zh":"中间这条空带是河界（楚河汉界）。有些棋子过河后走法会改变。"}},{"type":"explain","fen":"4k4/9/9/9/9/9/9/9/9/3K5 w - - 0 1","highlights":[{"square":"d0","kind":"hint"},{"square":"d1","kind":"hint"},{"square":"d2","kind":"hint"},{"square":"d7","kind":"hint"},{"square":"d8","kind":"hint"},{"square":"d9","kind":"hint"},{"square":"e0","kind":"hint"},{"square":"e1","kind":"hint"},{"square":"e2","kind":"hint"},{"square":"e7","kind":"hint"},{"square":"e8","kind":"hint"},{"square":"e9","kind":"hint"},{"square":"f0","kind":"hint"},{"square":"f1","kind":"hint"},{"square":"f2","kind":"hint"},{"square":"f7","kind":"hint"},{"square":"f8","kind":"hint"},{"square":"f9","kind":"hint"}],"text":{"en":"Each side has a palace: the 3×3 points with the diagonal lines. The general and the advisors must stay inside it.","zh":"双方各有一个九宫：画有斜线的3×3个点。将（帅）和士（仕）不能离开九宫。"}},{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","text":{"en":"Each side has 16 pieces: a general, two advisors, two elephants, two horses, two chariots, two cannons and five soldiers. Red moves first.","zh":"双方各有16个棋子：将（帅）一个，士、象、马、车、炮各两个，兵（卒）五个。红方先走。"}},{"type":"quiz","text":{"en":"Where do the pieces stand?","zh":"棋子放在哪里？"},"options":[{"text":{"en":"On the points where lines cross","zh":"线的交叉点上"},"correct":true},{"text":{"en":"Inside the squares","zh":"格子里面"}}],"explanation":{"en":"Right: Xiangqi pieces always stand on points.","zh":"对：象棋棋子总是放在交叉点上。"}},{"type":"quiz","text":{"en":"Who moves first?","zh":"哪一方先走？"},"options":[{"text":{"en":"Red","zh":"红方"},"correct":true},{"text":{"en":"Black","zh":"黑方"}}],"explanation":{"en":"Red always makes the first move.","zh":"总是红方先走。"}}]},{"id":"the-cannon","title":{"en":"The Cannon","zh":"炮"},"summary":{"en":"Moves like a chariot, captures by jumping one screen.","zh":"走法像车，吃子要隔一个子（炮架）。"},"steps":[{"type":"show-moves","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","square":"h2","text":{"en":"The cannon moves like a chariot. But to capture, it must jump over exactly one piece. From h2 it can take the horse on h9 by jumping the cannon on h7.","zh":"炮的走法和车一样，但吃子时必须隔一个子。h2的炮可以隔着h7的炮打掉h9的马。"}},{"type":"find-move","fen":"3k5/9/9/4r4/9/9/4P4/9/4C4/4K4 w - - 0 1","accept":["e1e6"],"text":{"en":"Use your soldier as a screen and capture the chariot.","zh":"用你的兵当炮架，打掉黑车。"},"hint":{"en":"Count the pieces between your cannon and the chariot.","zh":"数一数炮和车之间有几个子。"},"wrong":{"en":"That doesn't capture the chariot.","zh":"这步没有吃到车。"},"success":{"en":"Boom! The soldier was the screen (炮架).","zh":"打掉了！兵就是炮架。"}},{"type":"find-move","fen":"4k4/4a4/9/9/1C7/9/9/9/9/3K5 w - - 0 1","accept":["b5e5"],"text":{"en":"Give check with your cannon. The black advisor can be your screen.","zh":"用炮将军，黑士可以当你的炮架。"},"hint":{"en":"Line your cannon up with the black general.","zh":"把炮移到黑将的那条纵线上。"},"wrong":{"en":"That isn't check.","zh":"这步不是将军。"},"success":{"en":"Check! The advisor in front of the general became your screen.","zh":"将军！老将前面的士成了你的炮架。"}},{"type":"quiz","text":{"en":"How many pieces must be between a cannon and the piece it captures?","zh":"炮吃子时，中间要隔几个子？"},"options":[{"text":{"en":"Exactly one","zh":"正好一个"},"correct":true},{"text":{"en":"None","zh":"不用隔"}},{"text":{"en":"Any number","zh":"几个都行"}}],"explanation":{"en":"Exactly one: that piece is called the screen (炮架).","zh":"正好一个，这个子叫“炮架”。"}}]},{"id":"the-chariot","title":{"en":"The Chariot","zh":"车"},"summary":{"en":"Any distance along a line: the strongest piece.","zh":"沿直线走任意距离，是最强的棋子。"},"steps":[{"type":"show-moves","fen":"3k5/9/9/9/9/4R4/9/9/9/4K4 w - - 0 1","square":"e4","text":{"en":"The chariot moves any number of points along a file or rank, as long as nothing is in the way.","zh":"车沿纵线或横线走，只要路上没有棋子，走多远都行。"}},{"type":"capture-stars","fen":"3k5/9/9/9/9/9/9/9/9/R3K4 w - - 0 1","square":"a0","stars":["a5","f5","f8"],"maxMoves":5,"text":{"en":"Collect the stars with your chariot in as few moves as you can.","zh":"用车吃掉星星，步数越少越好。"}},{"type":"find-move","fen":"3k5/9/6n2/9/9/9/9/9/9/4K1R2 w - - 0 1","accept":["g0g7"],"text":{"en":"The black horse is unprotected. Take it!","zh":"黑马没有保护，吃掉它！"},"hint":{"en":"Your chariot has a clear path up its file.","zh":"你的车沿着纵线一路畅通。"},"wrong":{"en":"Look for a capture.","zh":"找一步吃子的棋。"},"success":{"en":"Free piece! A chariot is worth about two horses.","zh":"白得一子！一个车大约值两个马。"}},{"type":"quiz","text":{"en":"Which piece is usually the strongest?","zh":"哪个棋子通常最强？"},"options":[{"text":{"en":"The chariot","zh":"车"},"correct":true},{"text":{"en":"The horse","zh":"马"}},{"text":{"en":"The soldier","zh":"兵"}}],"explanation":{"en":"The chariot controls whole lines. A saying goes: 三步不出车，必定要输棋 — if your chariots aren't out within three moves, you're in trouble.","zh":"车能控制整条线。俗话说“三步不出车，必定要输棋”。"}}]},{"id":"the-elephant","title":{"en":"The Elephant","zh":"相象"},"summary":{"en":"Two points diagonally, never across the river.","zh":"斜走两步（走田字），不能过河。"},"steps":[{"type":"show-moves","fen":"3k5/9/9/9/9/9/9/4B4/9/4K4 w - - 0 1","square":"e2","text":{"en":"The elephant moves exactly two points diagonally (a 田 shape) and can never cross the river.","zh":"相（象）斜走两格，走“田”字，而且不能过河。"}},{"type":"show-moves","fen":"3k5/9/9/9/9/9/3N5/4B4/9/4K4 w - - 0 1","square":"e2","text":{"en":"The point in the middle of its move is the elephant's eye. A piece there blocks that move (塞象眼). Here the horse on d3 blocks the jump to c4.","zh":"相走田字的中心叫“象眼”。象眼上有棋子，就不能走那一步（塞象眼）。这里d3的马挡住了去c4的路。"}},{"type":"capture-stars","fen":"3k5/9/9/9/9/9/9/9/9/2B1K4 w - - 0 1","square":"c0","stars":["e2","g4"],"maxMoves":4,"text":{"en":"Collect the stars with your elephant.","zh":"用相吃掉星星。"}},{"type":"quiz","text":{"en":"Can the elephant cross the river?","zh":"相可以过河吗？"},"options":[{"text":{"en":"No, never","zh":"不能"},"correct":true},{"text":{"en":"Yes","zh":"可以"}}],"explanation":{"en":"The elephant always stays on its own side. It is a defender.","zh":"相永远留在自己一方，是防守的棋子。"}}]},{"id":"the-general","title":{"en":"The General","zh":"将帅"},"summary":{"en":"One step at a time, inside the palace.","zh":"每次走一步，不出九宫。"},"steps":[{"type":"explain","fen":"rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1","highlights":[{"square":"e0","kind":"hint"},{"square":"e9","kind":"hint"}],"text":{"en":"The general (帅 for Red, 将 for Black) is the most important piece. If your general is trapped, you lose.","zh":"将帅是最重要的棋子。老将被困死，就输了。"}},{"type":"show-moves","fen":"3k5/9/3n5/9/9/9/9/9/4K4/9 w - - 0 1","square":"e1","text":{"en":"The general moves one point at a time along a line: forward, back or sideways. It never moves diagonally.","zh":"将帅每次沿直线走一步：前进、后退或横走，不能斜走。"}},{"type":"capture-stars","fen":"3k5/9/3n5/9/9/9/9/9/9/4K4 w - - 0 1","square":"e0","stars":["f1","d2"],"maxMoves":6,"text":{"en":"Move your general to collect both stars. Remember: it can't leave the palace.","zh":"走动老帅，吃掉两颗星星。记住：不能出九宫。"}},{"type":"find-move","fen":"3k5/9/3nr4/9/9/9/9/9/4K4/9 w - - 0 1","accept":["e1d1","e1f1"],"text":{"en":"The black chariot gives check along the file! Move your general out of its line.","zh":"黑车在纵线上将军！把老帅移出这条线。"},"hint":{"en":"Step sideways, off the e-file.","zh":"横走一步，离开这条纵线。"},"wrong":{"en":"Your general is still on the chariot's line.","zh":"老帅还在车的攻击线上。"},"success":{"en":"Safe! Stepping out of the line is one way to escape check.","zh":"安全了！走出攻击线是应将的一种方法。"}},{"type":"quiz","text":{"en":"Can the general leave the palace?","zh":"将帅可以走出九宫吗？"},"options":[{"text":{"en":"Never","zh":"绝对不能"},"correct":true},{"text":{"en":"Yes, after crossing the river","zh":"过河以后可以"}},{"text":{"en":"Only to capture","zh":"只有吃子时可以"}}],"explanation":{"en":"The general always stays in its palace.","zh":"将帅永远不能离开九宫。"}}]},{"id":"the-horse","title":{"en":"The Horse","zh":"马"},"summary":{"en":"One step straight, then one diagonally — unless its leg is blocked.","zh":"先直走一步，再斜走一步——马腿被绊住就不行。"},"steps":[{"type":"show-moves","fen":"3k5/9/9/9/9/4N4/9/9/9/4K4 w - - 0 1","square":"e4","text":{"en":"The horse moves one point straight and then one point diagonally outward (a 日 shape). From the middle it has eight moves.","zh":"马先直走一步，再向外斜走一步，走“日”字。在中间时有八个去处。"}},{"type":"show-moves","fen":"3k5/9/9/9/4P4/4N4/9/9/9/4K4 w - - 0 1","square":"e4","text":{"en":"If a piece stands right next to the horse, it blocks the horse's leg (蹩马腿). The soldier on e5 stops the jumps to d6 and f6.","zh":"如果马旁边紧挨着有棋子，就绊住了马腿（蹩马腿）。e5的兵挡住了去d6和f6的路。"}},{"type":"capture-stars","fen":"3k5/9/9/9/9/9/9/9/9/1N2K4 w - - 0 1","square":"b0","stars":["c2","d4","f5"],"maxMoves":6,"text":{"en":"Hop your horse to collect the stars.","zh":"跳马吃掉所有星星。"}},{"type":"find-move","fen":"3k5/6c2/3r5/9/9/4N4/9/9/9/4K4 w - - 0 1","accept":["e4f6"],"text":{"en":"Find a horse move that attacks the chariot and the cannon at the same time.","zh":"找一步马，同时攻击黑车和黑炮。"},"hint":{"en":"Look at the point between them, in front of your horse.","zh":"看看马前面、它们俩中间的位置。"},"wrong":{"en":"That attacks only one piece, or none.","zh":"这步只攻击了一个子，或者都没攻击到。"},"success":{"en":"A fork! Black can only save one of them.","zh":"捉双！黑方只能救一个。"}},{"type":"quiz","text":{"en":"A piece stands right next to the horse in the direction it wants to go. Can it jump that way?","zh":"马要走的方向上紧挨着有一个棋子，马能跳过去吗？"},"options":[{"text":{"en":"No, its leg is blocked","zh":"不能，马腿被绊住了"},"correct":true},{"text":{"en":"Yes, horses jump over pieces","zh":"能，马可以跳过棋子"}}],"explanation":{"en":"Unlike the chess knight, the Xiangqi horse can be blocked.","zh":"和国际象棋的马不同，象棋的马会被绊腿。"}}]},{"id":"the-soldier","title":{"en":"The Soldier","zh":"兵卒"},"summary":{"en":"Forward only; sideways too after crossing the river.","zh":"只能前进，过河后也能横走。"},"steps":[{"type":"show-moves","fen":"3k5/9/9/9/9/9/4P4/9/9/4K4 w - - 0 1","square":"e3","text":{"en":"Before crossing the river, a soldier can only move one point forward.","zh":"兵在过河前只能向前走一步。"}},{"type":"show-moves","fen":"3k5/9/9/9/4P4/9/9/9/9/4K4 w - - 0 1","square":"e5","text":{"en":"Once across the river, it may also move one point sideways. It still never moves backward.","zh":"过河以后，兵也可以横走一步，但永远不能后退。"}},{"type":"capture-stars","fen":"3k5/9/9/9/9/9/2P6/9/9/4K4 w - - 0 1","square":"c3","stars":["c5","d6"],"maxMoves":4,"text":{"en":"March your soldier across the river to collect the stars.","zh":"让兵过河，吃掉星星。"}},{"type":"quiz","text":{"en":"When can a soldier move backward?","zh":"兵什么时候可以后退？"},"options":[{"text":{"en":"Never","zh":"永远不能"},"correct":true},{"text":{"en":"After crossing the river","zh":"过河以后"}},{"text":{"en":"When it reaches the last rank","zh":"走到底线时"}}],"explanation":{"en":"Soldiers only go forward (and sideways after the river). They never retreat.","zh":"兵只能前进（过河后可以横走），永不后退。"}}]}];
